function runDemo(args){
  var a=args.attrs;
  var power=Math.round(a.strength*0.30+a.speed*0.15+a.durability*0.20+a.energy*0.20+a.skill*0.15);
  var stamina=Math.round(a.durability*0.50+a.energy*0.30+a.strength*0.20);
  var tier=power>=90?'God-tier':power>=80?'Elite':power>=65?'Heroic':power>=45?'Skilled':'Developing';
  return {character:args.name, power_index:power, stamina_rating:stamina,
    tier:tier, rank_label:tier+' combatant'};
}
console.log(JSON.stringify(runDemo({"attrs": {"durability": 97, "energy": 96, "skill": 95, "speed": 98, "strength": 99}, "name": "King Kong", "seed": 1})));

